// Improved Parse Plan Code for n8n
// This handles AI outputs that may include text before/after the JSON

const ctx = $('Merge Files').item.json;
const raw = $('AI Plan').item.json;
let plan;
let out = '';

// Extract the output text from AI Plan
if (raw?.output) {
  if (typeof raw.output === 'string') out = raw.output;
  else if (typeof raw.output === 'object') out = JSON.stringify(raw.output);
}
if (!out && raw?.text) out = String(raw.text);

// Handle file creation from intermediate steps
const filesCreated = [];
const steps = raw?.intermediateSteps || [];
for (const step of steps) {
  const obs = step?.observation || step?.result || '';
  if (typeof obs === 'string' && obs.includes('Success: Created')) {
    const match = obs.match(/Created\s+(.+)/);
    if (match) filesCreated.push(match[1].trim());
  }
}

try {
  // IMPROVED: Try multiple regex patterns to extract JSON
  let jsonStr = null;

  // Pattern 1: Look for JSON between ``` blocks (if AI used markdown)
  const markdownMatch = out.match(/```(?:json)?\s*(\{[\s\S]*?\})\s*```/);
  if (markdownMatch) {
    jsonStr = markdownMatch[1];
  }

  // Pattern 2: Look for JSON object with humanSummary (original pattern, but improved)
  if (!jsonStr) {
    // Match from first { to last } that contains "humanSummary"
    const match = out.match(/\{[\s\S]*?"humanSummary"[\s\S]*\}/);
    if (match) {
      jsonStr = match[0];
      // Try to find the complete JSON object by counting braces
      let braceCount = 0;
      let start = -1;
      let end = -1;
      for (let i = 0; i < out.length; i++) {
        if (out[i] === '{') {
          if (start === -1) start = i;
          braceCount++;
        } else if (out[i] === '}') {
          braceCount--;
          if (braceCount === 0 && start !== -1) {
            end = i + 1;
            const candidate = out.substring(start, end);
            if (candidate.includes('"humanSummary"')) {
              jsonStr = candidate;
              break;
            }
          }
        }
      }
    }
  }

  // Pattern 3: Last resort - look for any valid JSON object
  if (!jsonStr) {
    const jsonMatches = out.match(/\{[^{}]*(?:\{[^{}]*\}[^{}]*)*\}/g);
    if (jsonMatches) {
      // Find the one with humanSummary
      for (const candidate of jsonMatches) {
        if (candidate.includes('"humanSummary"') || candidate.includes("'humanSummary'")) {
          jsonStr = candidate;
          break;
        }
      }
    }
  }

  if (jsonStr) {
    // Clean up the JSON string
    jsonStr = jsonStr
      .replace(/[\x00-\x1F\x7F]/g, ' ')  // Remove control characters
      .replace(/,\s*}/g, '}')             // Remove trailing commas before }
      .replace(/,\s*]/g, ']')             // Remove trailing commas before ]
      .trim();

    plan = JSON.parse(jsonStr);
  } else if (filesCreated.length > 0) {
    // Fallback: if files were created but no JSON found
    plan = {
      humanSummary: `Created ${filesCreated.length} file(s): ${filesCreated.join(', ')}. Refresh to see changes!`,
      unifiedDiff: '',
      fileTargets: filesCreated.map(f => ({ path: f, action: 'create' })),
      warnings: ['JSON not found in AI output, using file creation data']
    };
  } else {
    // Last fallback
    plan = {
      humanSummary: 'Please try again with a more specific request.',
      unifiedDiff: '',
      fileTargets: [],
      warnings: ['Could not parse JSON from AI output: ' + out.substring(0, 200)]
    };
  }
} catch (e) {
  plan = {
    humanSummary: filesCreated.length > 0 ? `Created: ${filesCreated.join(', ')}` : 'Error parsing AI response.',
    unifiedDiff: '',
    fileTargets: filesCreated.map(f => ({ path: f, action: 'create' })),
    warnings: ['Parse error: ' + e.message + ' | Output: ' + out.substring(0, 200)]
  };
}

// Ensure all required fields exist with correct types
plan.warnings = Array.isArray(plan.warnings) ? plan.warnings : [];
plan.unifiedDiff = typeof plan.unifiedDiff === 'string' ? plan.unifiedDiff : '';
plan.fileTargets = Array.isArray(plan.fileTargets) ? plan.fileTargets : [];
plan.humanSummary = plan.humanSummary || 'Changes processed.';

return [{ json: { ...ctx, plan, filesCreated } }];

const ctx = $input.first().json;
if (!ctx?.site) throw new Error('Missing site');
if (!ctx?.plan) throw new Error('Missing plan');
return [{ json: ctx }];

const ctx = $('Guardrails').item.json;
const applyResp = $input.first().json;
const filesChanged = applyResp.filesChanged || [];
const applyOk = applyResp.ok || false;
if (!applyOk && applyResp.error) {
  ctx.plan.warnings = ctx.plan.warnings || [];
  ctx.plan.warnings.push('Failed to apply: ' + applyResp.error);
}
return [{ json: { ...ctx, filesChanged, applyOk } }];
